  "times.py": "'''Timestamp parsing and normalization for the synthetic snapshot pipeline.'''

from datetime import datetime, timezone

__all__ = ['instant']


def instant(value):
    '''Return *value* normalized to a timezone-aware UTC ``datetime``.

    Accepts ISO8601 strings accepted by ``datetime.fromisoformat``
    (including a trailing ``Z``) and ``datetime`` instances.  The value must
    be timezone aware with a non-``None`` ``utcoffset``; anything else,
    including unparseable strings and naive values, raises ``ValueError``.
    '''
    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = datetime.fromisoformat(value)
        except ValueError:
            if value.endswith('Z') or value.endswith('z'):
                try:
                    parsed = datetime.fromisoformat(value[:-1] + '+00:00')
                except ValueError:
                    raise ValueError(f'invalid instant: {value!r}') from None
            else:
                raise ValueError(f'invalid instant: {value!r}') from None
    else:
        raise ValueError(f'invalid instant: {value!r}')
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError(f'instant is not timezone-aware: {value!r}')
    return parsed.astimezone(timezone.utc)
