  "quotes.py": "'''American-odds probability conversion and per-book quote selection.'''

import math

from times import instant

__all__ = ['probability', 'select']


def _is_nonempty_str(value):
    return isinstance(value, str) and value != ''


def probability(value):
    '''Convert American odds *value* into a win probability ``float``.

    Positive odds ``v`` yield ``100 / (v + 100)``; negative odds yield
    ``(-v) / ((-v) + 100)``.  Accepted inputs are finite ``int`` or
    ``float`` values (``bool`` excluded) or strings convertible by
    ``float``.  The magnitude must be at least 100 and the value must be
    finite and representable as a ``float``; otherwise ``ValueError`` is
    raised.
    '''
    if isinstance(value, bool):
        raise ValueError(f'bool is not valid odds: {value!r}')
    if isinstance(value, (int, float)):
        try:
            number = float(value)
        except (OverflowError, ValueError) as error:
            raise ValueError(
                f'odds not representable as a finite float: {value!r}') from error
    elif isinstance(value, str):
        try:
            number = float(value)
        except (OverflowError, ValueError) as error:
            raise ValueError(
                f'odds string not float-convertible: {value!r}') from error
    else:
        raise ValueError(f'unsupported odds type: {type(value).__name__}')
    if not math.isfinite(number):
        raise ValueError(f'odds must be finite: {value!r}')
    if abs(number) < 100.0:
        raise ValueError(f'odds magnitude below 100: {value!r}')
    if number > 0:
        return 100.0 / (number + 100.0)
    return (-number) / ((-number) + 100.0)


def select(rows, event, asof):
    '''Select the greatest eligible quote per book for *event* as of *asof*.

    A row (a dict) is eligible when its ``event`` equals *event*, its
    ``observed_at`` is at or before *asof*, *asof* is strictly before its
    ``expires_at``, and its ``last_update`` is at or before its
    ``observed_at``.  Malformed rows are skipped; inputs are never mutated
    and the chosen row is returned uncopied.  Per book the greatest
    ``observed_at`` wins; absolute-time ties prefer the lexicographically
    smallest ``id``; equal instant and id keep the first eligible input row
    regardless of other fields.  Books without eligible quotes are omitted.
    Returns ``{book: {'row': <original input dict>, 'probability': float}}``.
    '''
    if not _is_nonempty_str(event):
        raise ValueError('event must be a nonempty string')
    asof_instant = instant(asof)

    best = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        quote_id = row.get('id')
        book = row.get('book')
        row_event = row.get('event')
        if not (_is_nonempty_str(quote_id)
                and _is_nonempty_str(book)
                and _is_nonempty_str(row_event)):
            continue
        if row_event != event:
            continue
        try:
            observed = instant(row.get('observed_at'))
            expires = instant(row.get('expires_at'))
            updated = instant(row.get('last_update'))
            odds = probability(row.get('odds'))
        except ValueError:
            continue
        if not (observed <= asof_instant < expires):
            continue
        if updated > observed:
            continue
        current = best.get(book)
        if (current is None
                or observed > current[0]
                or (observed == current[0] and quote_id < current[1])):
            best[book] = (observed, quote_id, row, odds)
    return {
        book: {'row': entry[2], 'probability': entry[3]}
        for book, entry in best.items()
    }
