  "pipeline.py": "'''Integrated fabricated snapshot pipeline entry point.'''

from quotes import select as select_quotes
from runs import reconcile as reconcile_runs
from times import instant

__all__ = ['snapshot']


def snapshot(quote_rows, run_rows, event, asof):
    '''Build the integrated snapshot for *event* as of *asof*.

    *asof* and *event* are validated before either input list is inspected.
    Quote selection and run reconciliation are independent.
    ``successful_rows`` sums ``downloaded_rows`` once per selected job whose
    status is ``ok`` or ``partial``; ``failures``, ``partial_jobs`` and
    ``unknown_jobs`` list the selected jobs whose status is ``failed``,
    ``partial`` and ``pending``, respectively, sorted.
    '''
    asof_instant = instant(asof)
    if not isinstance(event, str) or event == '':
        raise ValueError('event must be a nonempty string')

    quote_selection = select_quotes(quote_rows, event, asof_instant)
    run_selection = reconcile_runs(run_rows, asof_instant)

    successful_rows = 0
    failures = []
    partial_jobs = []
    unknown_jobs = []
    for job, row in run_selection.items():
        status = row.get('status')
        if status == 'ok' or status == 'partial':
            successful_rows += row.get('downloaded_rows', 0)
        elif status == 'failed':
            failures.append(job)
        elif status == 'pending':
            unknown_jobs.append(job)

    return {
        'quotes': quote_selection,
        'runs': run_selection,
        'successful_rows': successful_rows,
        'failures': sorted(failures),
        'partial_jobs': sorted(partial_jobs),
        'unknown_jobs': sorted(unknown_jobs),
    }
